        list.add(nums[i]);
    }
    result.add(list);
    int k = 0;
    while (k < nums.length) {
        if (list.get(k) != nums[k]) {
            break;
        }
        k++;
    }
    if (k == nums.length) {
        return result;
    }
    List<List<Integer>> newResult = new ArrayList<>();
    for (List<Integer> l : result) {
        for (int i = 0; i < l.size(); i++) {
            if (l.get(i) == nums[k]) {
                List<Integer> newList = new ArrayList<>(l);
                newList.remove(i);
                newList.add(k, nums[k]);
                newResult.add(newList);
            }
        }
    }
    return newResult;
}
