      }  
      int l = indexes.length - 1;  
      for (int i = k + 1; i < n; i++) {  
         if (indexes[i] < indexes[k]) {  
            l = i;  
         }  
      }  
      swap(indexes, k, l);  
      reverse(indexes, k + 1, n - 1);  
   }  
   return result;  
}   

private void swap(int[] indexes, int i, int j) {  
   int t = indexes[i];  
   indexes[i] = indexes[j];  
   indexes[j] = t;  
}   

private void reverse(int[] indexes, int i, int j) {  
   while (i < j) {  
      swap(indexes, i, j);  
      i++;  
      j--;  
   }  
}


