import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class PermuteRecursion {
    public static void main(String[] args) {
        int[] nums = { 1, 2, 3 };
        System.out.println(permute(nums));
    }

    public static List<List<Integer>> permute(int[] nums) {
        List<List<Integer>> result = new ArrayList<>();
        permuteHelper(nums, 0, nums.length - 1, result);
        return result;
    }

    public static void permuteHelper(int[] nums, int start, int end, List<List<Integer>> result) {
        if (start == end) {
            result.add(new ArrayList<>(Arrays.asList(nums)));
        } else {
            for (int i = start; i <= end; i++) {
                swap(nums, start, i);
                permuteHelper(nums, start + 1, end, result);
                swap(nums, start, i);
            }
        }
    }

    public static void swap(int[] nums, int i, int j) {
        int temp = nums[i];
        nums[i] = nums[j];
        nums[j] = temp;
    }
}
