public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> permutations = new ArrayList<>();
    if (nums == null || nums.length == 0) {
        return permutations;
    }
    int n = nums.length;
    boolean[] visited = new boolean[n];
    List<Integer> current = new ArrayList<>();
    backtrack(nums, n, visited, current, permutations);
    return permutations;
}

private void backtrack(int[] nums, int n, boolean[] visited, List<Integer> current, List<List<Integer>> permutations) {
    if (current.size() == n) {
        permutations.add(new ArrayList<>(current));
        return;
    }
    for (int i = 0; i < n; i++) {
        if (visited[i]) {
            continue;
        }
        visited[i] = true;
        current.add(nums[i]);
        backtrack(nums, n, visited, current, permutations);
        visited[i] = false;
        current.remove(current.size() - 1);
    }
}
