public static int countOilDeposits(char[][] grid)
        {
            int width = grid[0].length;
            int height = grid.length;

            // Initialize number of deposits to 0
            int numDeposits = 0;

            // Iterate through grid and check for oil pockets
            for (int i = 0; i < height; i++) {
                for (int j = 0; j < width; j++) {
                    // If the current position is an oil pocket, assign ID
                    if (grid[i][j] == '@') {
                        // Calculate the unique ID for the deposit
                        int ID = i*width + j;

                        // Flood-fill the adjacent positions with the same ID
                        floodFill(grid, ID, width, height, i, j);

                        // Update the number of ID's generated as deposits
                        numDeposits++;
                    }
                }
            }

            // Return the number of distinct oil deposits
            return numDeposits;
        }

        // Flood-fills adjacent positions with the same ID
        private static void floodFill(char[][] grid, int ID, int width, int height, int x, int y) {
            // Base case: out-of-bounds or position not containing oil ('@')
            if (!(x >= 0 && x < height && y >= 0 && y < width) || grid[x][y] != '@') {
                return;
            }

            // Label the current position with the ID
            grid[x][y] = (char) ID;

            // Recursively call flood-fill on the adjacent positions
            floodFill(grid, ID, width, height, x - 1, y);
            floodFill(grid, ID, width, height, x + 1, y);
            floodFill(grid, ID, width, height, x, y - 1);
            floodFill(grid, ID, width, height, x, y + 1);
        }
