private static void dfs(char[][] grid, int row, int column, int count) {
    if (row < 0 || column < 0 || row >= grid.length || column >= grid[row].length || grid[row][column] != '@') {
        return;
    }

    count++;
    grid[row][column] = 0;

    dfs(grid, row - 1, column, count);
    dfs(grid, row + 1, column, count);
    dfs(grid, row, column - 1, count);
    dfs(grid, row, column + 1, count);
}
