    public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
        if (n <= 0 || start.length != 2 || end.length != 2 || paths.length != n || paths[0].length != n) {
            return "cannot be travelled";
        }

        // Find the starting and ending n-tersection indices
        int startIndex = getNtersectionIndex(start, n);
        int endIndex = getNtersectionIndex(end, n);

        // Check if the starting and ending n-tersections are adjacent
        if (isAdjacent(startIndex, endIndex, paths)) {
            return "can be travelled";
        }

        // Initialize a boolean array to keep track of visited n-tersections
        boolean[] visited = new boolean[n];
        visited[startIndex] = true;

        // Initialize a queue to keep track of the BFT
        Queue<Integer> queue = new LinkedList<>();
        queue.offer(startIndex);

        while (!queue.isEmpty()) {
            int currentIndex = queue.poll();
            for (int neighborIndex : getNeighborIndices(currentIndex, paths)) {
                if (!visited[neighborIndex]) {
                    visited[neighborIndex] = true;
                    queue.offer(neighborIndex);
                }
                if (neighborIndex == endIndex) {
                    return "can be travelled";
                }
            }
        }

        return "cannot be travelled";
    }

    private static int getNtersectionIndex(int[] coordinates, int n) {
        return coordinates[0] + coordinates[1] * n;
    }

    private static boolean isAdjacent(int ntersection1Index, int ntersection2Index, int[][] paths) {
        for (int i = 0; i < paths.length; i++) {
            if (paths[ntersection1Index][i] == 1 && i == ntersection2Index) {
                return true;
            }
        }
        return false;
    }

    private static List<Integer> getNeighborIndices(int ntersectionIndex, int[][] paths) {
        List<Integer> neighbors = new ArrayList<>();
        for (int i = 0; i < paths.length; i++) {
            if (paths[ntersectionIndex][i] == 1) {
                neighbors.add(i);
            }
        }
        return neighbors;
    }
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Initialize a boolean array to keep track of visited n-tersections
    boolean[] visited = new boolean[n];
    // Initialize a queue to perform BFS
    Queue<int[]> queue = new LinkedList<>();

    // Mark the starting n-tersection as visited and add it to the queue
    visited[start[0] * n + start[1]] = true;
    queue.offer(start);

    // Perform BFS
    while (!queue.isEmpty()) {
        int[] current = queue.poll();
        // If the ending n-tersection is reached, return "can be travelled"
        if (Arrays.equals(current, end)) {
            return "can be travelled";
        }
        // For each adjacent n-tersection, check if it is not visited and not a wall, and if so, mark it as visited and add it to the queue
        for (int[] neighbour : getNeighbours(current, paths)) {
            if (!visited[neighbour[0] * n + neighbour[1]] && !isWall(neighbour, paths)) {
                visited[neighbour[0] * n + neighbour[1]] = true;
                queue.offer(neighbour);
            }
        }
    }
    // If the ending n-tersection is not reached, return "cannot be travelled"
    return "cannot be travelled";
}

// A helper method to get the neighbouring n-tersections of a given n-tersection
private static int[][] getNeighbours(int[] current, int[][] paths) {
    int[] neighbours = new int[4][2];
    // Traverse the paths array to find the neighbouring n-tersections
    for (int i = 0; i < paths.length; i++) {
        int[] path = paths[i];
        if (path[0] == current[0] && path[1] == current[1]) {
            neighbours[0] = new int[] { path[2], path[3] };
        } else if (path[2] == current[0] && path[3] == current[1]) {
            neighbours[1] = new int[] { path[0], path[1] };
        }
    }
    return neighbours;
}

// A helper method to check if a given n-tersection is a wall
private static boolean isWall(int[] ntersection, int[][] paths) {
    // Traverse the paths array to find the neighbouring n-tersections
    for (int[] path : paths) {
        if (path[0] == ntersection[0] && path[1] == ntersection[1] || path[2] == ntersection[0] && path[3] == ntersection[1]) {
            return false;
        }
    }
    return true;
}

