public static boolean isSteppingNumber(int number) {
    if (number < 10) {
        return true;
    }

    // Convert the number to a string
    String numberString = String.valueOf(number);

    for (int i = 1; i < numberString.length(); i++) {
        // Get the current digit and the previous digit
