public static int longestLine(int[][] mat) {
    int m = mat.length;
    int n = mat[0].length;
    int maxLength = 0;
    int currentLength;
    //horizontal check
    for (int i = 0; i < m; i++) {
        currentLength = 0;
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                currentLength++;
            } else {
                maxLength = Math.max(maxLength, currentLength);
                currentLength = 0;
            }
        }
        maxLength = Math.max(maxLength, currentLength);
    }

    //vertical check
    for (int j = 0; j < n; j++) {
        currentLength = 0;
        for (int i = 0; i < m; i++) {
            if (mat[i][j] == 1) {
                currentLength++;
            } else {
                maxLength = Math.max(maxLength, currentLength);
                currentLength = 0;
            }
        }
        maxLength = Math.max(maxLength, currentLength);
    }

    //diagonal check
    for (int i = 0; i < m; i++) {
        for (int j = 0; j + i < n; j++) {
            if (mat[i][j] == 1) {
                currentLength = 1;
                while (i + 1 < m && j + 1 < n && mat[i + 1][j + 1] == 1) {
                    currentLength++;
                    i++;
                    j++;
                }
                maxLength = Math.max(maxLength, currentLength);
            }
        }
    }

    //anti-diagonal check
    for (int i = 0; i < m; i++) {
        for (int j = n - 1; j - i >= 0; j--) {
            if (mat[i][j] == 1) {
                currentLength = 1;
                while (i + 1 < m && j - 1 >= 0 && mat[i + 1][j - 1] == 1) {
                    currentLength++;
                    i++;
                    j--;
                }
                maxLength = Math.max(maxLength, currentLength);
            }
        }
    }
    return maxLength;
}
