public static int longestLine(int[][] mat) {
    int m = mat.length;
    int n = mat[0].length;
    int[][] dp = new int[m][n];
    int max = 0;

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            /*
            Calculate the length of the longest continuous line of 1s
            starting from (i, j) by checking the neighbor cells.
            */
            int line = 0;
            if (mat[i][j] == 1) {
                line++;
                if (i > 0 && mat[i - 1][j] == 1) {
                    line = Math.max(line, dp[i - 1][j] + 1);
                }
                if (j > 0 && mat[i][j - 1] == 1) {
                    line = Math.max(line, dp[i][j - 1] + 1);
                }
                if (i < m - 1 && mat[i + 1][j] == 1) {
                    line = Math.max(line, dp[i + 1][j] + 1);
                }
