public class SquarePermutations {
    public static int squarePermutations(int[] A) {
        Set<Set<Integer>> squarePairs = findSquarePairs(A);
        Set<Integer> permutations = new HashSet<>();
        generatePermutations(A, permutations, 0, A.length - 1, squarePairs);
        return permutations.size();
